import json
import re
import base64
import datetime
from zoneinfo import ZoneInfo

FILEABLE_TYPES = ("referral", "result", "imaging", "clinical_letter")
TYPE_LABELS = {
    "referral": "Referral",
    "result": "Test result",
    "imaging": "Imaging report",
    "clinical_letter": "Clinical letter",
}


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def delete_file(path):
    try:
        api.files.delete(file=path)
    except Exception:
        pass


def norm(s):
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", str(s or "").lower())).strip()


def practice_tz(practice):
    try:
        return ZoneInfo(str(practice.get("timezone") or "Australia/Sydney"))
    except Exception:
        return datetime.timezone.utc


def audit(slug, tz, source, action, target, summary, workq_item_id=""):
    # SK-13 format (healthcare-practice-management-foundation): one JSON line per action, practice-local ts.
    now_local = datetime.datetime.now(tz)
    path = "PracticeManager/AuditLog/" + slug + "-" + now_local.strftime("%Y-%m-%d") + ".jsonl"
    line = {
        "ts": now_local.isoformat(timespec="seconds"), "practice_slug": slug, "actor": "agent",
        "source": source, "action": action, "target": target, "summary": summary,
    }
    if workq_item_id:
        line["workq_item_id"] = workq_item_id
    try:
        try:
            existing = api.files.read(file=path) or ""
        except Exception:
            existing = ""
        if existing and not existing.endswith("\n"):
            existing += "\n"
        api.files.put(file=path, content=existing + json.dumps(line, sort_keys=True) + "\n")
    except Exception:
        pass


def fetch_attachment(message_id, attachment_id):
    """The attachment's bytes as standard base64, plus its name and content type."""
    att = api.connectors.invoke(
        server="m365-mail-read", tool="get_email_attachment",
        args={"messageId": message_id, "attachmentId": attachment_id, "heicToJpeg": True},
    ) or {}
    if isinstance(att, str):
        att = json.loads(att)
    return {
        "name": str(att.get("name") or "document"),
        "content_type": str(att.get("contentType") or "application/octet-stream"),
        "content_base64": str(att.get("contentBase64") or ""),
    }


def to_scratch(att):
    """Write the attachment to this run's scratch space so the AI can read the file itself."""
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", att["name"])[-80:] or "document"
    path = api.files.scratch_path(safe)
    with open(path, "wb") as fh:
        fh.write(base64.b64decode(att["content_base64"]))
    return path


def patient_name(p):
    return (str(p.get("first_name") or "") + " " + str(p.get("last_name") or "")).strip()


def find_patients(first, last, dob):
    """Cliniko patients whose first + last name match (case/punctuation-insensitive), narrowed by DOB when given."""
    if not last:
        return []
    try:
        res = api.connectors.invoke(
            server="cliniko-patients", tool="list_patients",
            args={"q": ["last_name:~" + str(last)], "per_page": 100},
        ) or {}
        rows = res.get("patients") or []
    except Exception:
        rows = []
    out = []
    for p in rows:
        if p.get("archived_at"):
            continue
        same_last = norm(p.get("last_name")) == norm(last)
        firsts = {norm(p.get("first_name")), norm(p.get("preferred_first_name"))}
        same_first = bool(first) and norm(first) in firsts
        if same_last and same_first:
            out.append(p)
    if dob:
        exact = [p for p in out if str(p.get("date_of_birth") or "")[:10] == str(dob)[:10]]
        return exact
    return out


def find_or_create_contact(referrer):
    """The referrer as a Cliniko contact: matched by email, then provider number, then name; created if new."""
    first = str(referrer.get("first_name") or "").strip()
    last = str(referrer.get("last_name") or "").strip()
    email = str(referrer.get("email") or "").strip().lower()
    provider = str(referrer.get("provider_number") or "").strip()
    if not last:
        return None, False
    try:
        res = api.connectors.invoke(
            server="cliniko-patients", tool="list_contacts",
            args={"q": ["last_name:~" + last], "per_page": 100},
        ) or {}
        rows = [c for c in (res.get("contacts") or []) if not c.get("archived_at") and not c.get("deleted_at")]
    except Exception:
        rows = []
    for c in rows:
        if email and str(c.get("email") or "").strip().lower() == email:
            return c, False
    for c in rows:
        if provider and str(c.get("provider_number") or "").strip() == provider:
            return c, False
    for c in rows:
        if norm(c.get("first_name")) == norm(first) and norm(c.get("last_name")) == norm(last):
            return c, False
    body = {"first_name": first or None, "last_name": last, "type_code": 1}  # 1 = Doctor
    for key in ("title", "company_name", "provider_number"):
        if referrer.get(key):
            body[key] = str(referrer.get(key))
    if email:
        body["email"] = email
    if referrer.get("doctor_type") in ("general_practitioner", "specialist"):
        body["doctor_type"] = referrer.get("doctor_type")
    created = api.connectors.invoke(server="cliniko-patients", tool="create_contact", args={"contact": body}) or {}
    return created, True


def file_document(patient_id, att, extracted, received_at):
    """Upload the file to the patient; for a referral also link the referrer contact and a patient case.
    Returns a dict describing what was done (for comments, notifications and the audit log)."""
    kind = str(extracted.get("document_type") or "clinical_letter")
    label = TYPE_LABELS.get(kind, "Document")
    referrer = extracted.get("referrer") or {}
    who = " ".join(x for x in [str(referrer.get("title") or ""), str(referrer.get("first_name") or ""),
                                str(referrer.get("last_name") or "")] if x).strip()
    description = (label + (" from " + who if who else "") + ", received " + str(received_at)[:10])[:255]
    uploaded = api.connectors.invoke(
        server="cliniko-clinical", tool="upload_patient_attachment",
        args={
            "patient_id": str(patient_id), "filename": att["name"][:255], "content_type": att["content_type"],
            "description": description, "content_base64": att["content_base64"],
        },
    ) or {}
    result = {"attachment_id": str(uploaded.get("id") or ""), "label": label, "description": description,
              "contact": None, "contact_created": False, "case_id": ""}
    if kind == "referral":
        contact, created = (None, False)
        try:
            contact, created = find_or_create_contact(referrer)
        except Exception:
            contact, created = (None, False)
        ref = extracted.get("referral") or {}
        case = {
            "patient_id": str(patient_id),
            "name": ("Referral" + (" - " + who if who else "") + " (" + str(received_at)[:10] + ")")[:255],
            "referral": True,
        }
        if contact and contact.get("id"):
            case["contact_id"] = str(contact.get("id"))
        if ref.get("referral_type") in ("medicare", "dva"):
            case["referral_type"] = ref.get("referral_type")
        for key in ("issue_date", "expiry_date"):
            if re.match(r"^\d{4}-\d{2}-\d{2}$", str(ref.get(key) or "")):
                case[key] = ref.get(key)
        try:
            sessions = int(ref.get("max_sessions") or 0)
        except Exception:
            sessions = 0
        if 1 <= sessions <= 300:
            case["max_sessions"] = sessions
        if result["attachment_id"]:
            case["patient_attachment_ids"] = [result["attachment_id"]]
        try:
            made = api.connectors.invoke(server="cliniko-patients", tool="create_patient_case",
                                         args={"patient_case": case}) or {}
            result["case_id"] = str(made.get("id") or "")
        except Exception as exc:
            result["case_error"] = str(exc)[:300]
        result["contact"] = contact
        result["contact_created"] = created
    return result


def summary_lines(res, patient_label):
    lines = ["Filed **" + res["label"] + "** on " + patient_label + " in Cliniko (attachment " + (res["attachment_id"] or "id not returned") + ")."]
    contact = res.get("contact") or {}
    if contact:
        lines.append(("Added the referrer as a new Cliniko contact: " if res.get("contact_created") else "Linked the existing contact: ")
                     + (str(contact.get("first_name") or "") + " " + str(contact.get("last_name") or "")).strip() + ".")
    if res.get("case_id"):
        lines.append("Created a referral case (" + res["case_id"] + ") with the file attached.")
    if res.get("case_error"):
        lines.append("Couldn't create the referral case: " + res["case_error"] + " - add it by hand in Cliniko.")
    return lines

SOURCE = "automation:Inbound document filing"
MAX_DOCS_PER_RUN = 10
MAX_PAGES = 5  # x 50 emails per run
AI_MAX_BYTES = 10 * 1024 * 1024  # what api.ai can read from a file (PDFs; images up to 5 MB)
READABLE = ("application/pdf", "image/png", "image/jpeg", "image/gif", "image/webp")
EXTRACT_PROMPT = (
    "You are filing documents that arrive by email at a healthcare clinic. Read the attached document and say what it "
    "is and who it is about. document_type is one of: referral (a GP or specialist referring the patient, incl. Medicare "
    "or DVA referrals), result (pathology/lab results), imaging (x-ray, ultrasound, MRI, CT report), clinical_letter "
    "(any other letter or report about a patient's care), not_clinical (bills, invoices, newsletters, marketing, "
    "anything not about a specific patient's care). patient is the person the document is about - copy names and date "
    "of birth exactly as printed (date as YYYY-MM-DD, or null if not printed). referrer is the doctor who wrote or sent "
    "it, if shown. For a referral, referral_type is medicare or dva only if the document says so, issue_date and "
    "expiry_date as YYYY-MM-DD if printed, max_sessions if a number of sessions is stated. summary is one short factual "
    "sentence of what the document is (no clinical interpretation). Use null for anything not printed - never guess."
)
EXTRACT_HINT = (
    '{"document_type": "referral|result|imaging|clinical_letter|not_clinical", '
    '"patient": {"first_name": "", "last_name": "", "date_of_birth": "YYYY-MM-DD or null"}, '
    '"referrer": {"title": "", "first_name": "", "last_name": "", "company_name": "", "email": "", '
    '"provider_number": "", "doctor_type": "general_practitioner|specialist|null"}, '
    '"referral": {"referral_type": "medicare|dva|null", "issue_date": null, "expiry_date": null, "max_sessions": null}, '
    '"summary": ""}'
)


def utc_iso(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    # Outlook only: Gmail practices would need the Gmail connector on every install, and Gmail is read-only anyway.
    if practice and str(practice.get("email_provider") or "outlook") == "outlook":
        practices.append({"slug": str(fname)[:-5], "practice": practice})

now = datetime.datetime.now(datetime.timezone.utc)
filed, queued, skipped, problems = 0, 0, 0, []
for p in practices[:1]:
    # One mailbox per connection: the automation reads the owner's Outlook, so it serves the first Outlook practice.
    slug, practice = p["slug"], p["practice"]
    tz = practice_tz(practice)
    reviewer = practice.get("reviewer_id") or ""
    state_path = "PracticeManager/DocumentIntake/" + slug + ".json"
    state = read_json(state_path, {}) or {}
    # First run: only look back one day, never the whole mailbox.
    cursor = str(state.get("scan_after") or utc_iso(now - datetime.timedelta(days=1)))
    done_ids = [str(x) for x in (state.get("done") or [])]
    last_seen = ""
    work = []
    for _page in range(MAX_PAGES):
        try:
            msgs = api.connectors.invoke(
                server="m365-mail-read", tool="list_emails",
                args={"folder": "inbox", "limit": 50, "receivedAfter": cursor, "oldestFirst": True},
            )
            msgs = msgs if isinstance(msgs, list) else ((msgs or {}).get("value") or [])
        except Exception as exc:
            problems.append("couldn't read the inbox: " + str(exc)[:200])
            msgs = []
        for m in msgs:
            last_seen = str(m.get("receivedDateTime") or last_seen)
            if m.get("hasAttachments") and str(m.get("id") or "") not in done_ids:
                work.append(m)
        if len(msgs) < 50 or not last_seen or len(work) >= MAX_DOCS_PER_RUN:
            break
        cursor = last_seen

    docs_this_run = 0
    stopped_at = ""  # receivedDateTime of the first email NOT finished this run (cap reached or a retryable failure)
    for m in work:
        message_id = str(m.get("id") or "")
        if docs_this_run >= MAX_DOCS_PER_RUN:
            stopped_at = str(m.get("receivedDateTime") or "")
            break
        sender = str((((m.get("from") or {}).get("emailAddress")) or {}).get("address") or "")
        subject = str(m.get("subject") or "(no subject)")
        received = str(m.get("receivedDateTime") or "")
        try:
            atts = api.connectors.invoke(server="m365-mail-read", tool="list_email_attachments", args={"id": message_id}) or []
            atts = atts if isinstance(atts, list) else (atts.get("value") or [])
        except Exception as exc:
            problems.append("couldn't list attachments on '" + subject + "': " + str(exc)[:200])
            stopped_at = received  # retried from here next run
            break
        retry = False
        for a in atts:
            if a.get("isInline") or str(a.get("kind") or "file") != "file":
                continue
            att_key = message_id + ":" + str(a.get("id") or "")
            if att_key in done_ids:
                continue  # already handled on an earlier run of a retried email
            ctype = str(a.get("contentType") or "").lower()
            name = str(a.get("name") or "")
            if not (ctype in READABLE or name.lower().endswith((".pdf", ".heic", ".heif", ".jpg", ".jpeg", ".png"))):
                continue
            docs_this_run += 1
            try:
                att = fetch_attachment(message_id, str(a.get("id") or ""))
            except Exception as exc:
                problems.append("couldn't download '" + name + "': " + str(exc)[:200])
                retry = True
                break
            size = len(att["content_base64"]) * 3 // 4
            extracted = {}
            if size <= AI_MAX_BYTES:
                try:
                    extracted = api.ai.extract(prompt=EXTRACT_PROMPT, schema_hint=EXTRACT_HINT, scratch_file=to_scratch(att),
                                               input="Email from " + sender + ", subject: " + subject)
                except Exception as exc:
                    problems.append("couldn't read '" + name + "': " + str(exc)[:200])
            extracted = extracted if isinstance(extracted, dict) else {}
            kind = str(extracted.get("document_type") or "")
            if kind == "not_clinical":
                skipped += 1
                done_ids.append(att_key)
                continue
            pat = extracted.get("patient") or {}
            first, last = str(pat.get("first_name") or "").strip(), str(pat.get("last_name") or "").strip()
            dob = str(pat.get("date_of_birth") or "").strip()
            dob = dob if re.match(r"^\d{4}-\d{2}-\d{2}$", dob) else ""
            candidates = find_patients(first, last, dob) if kind in FILEABLE_TYPES else []
            read_as = (TYPE_LABELS.get(kind, "Unreadable document") + " about " + (first + " " + last).strip()
                       + (" (DOB " + dob + ")" if dob else "")) if kind in FILEABLE_TYPES else "a document the AI couldn't read"

            if kind in FILEABLE_TYPES and dob and len(candidates) == 1:
                # Certain: one patient with the same name AND date of birth.
                patient = candidates[0]
                try:
                    res = file_document(patient.get("id"), att, extracted, received)
                except Exception as exc:
                    problems.append("couldn't file '" + name + "': " + str(exc)[:200])
                    retry = True
                    break
                label = patient_name(patient)
                audit(slug, tz, SOURCE, "edited", {"kind": "patient_attachment", "id": res["attachment_id"]},
                      "Filed " + res["label"].lower() + " '" + name + "' on " + label + " (name and date of birth matched)")
                body = "\n".join(summary_lines(res, label)) + "\n\nFrom " + sender + ", '" + subject + "'."
                if kind in ("result", "imaging"):
                    api.workq.create(
                        title="Review new " + res["label"].lower() + ": " + label, scope="org",
                        description=body + "\n\n" + str(extracted.get("summary") or ""),
                        priority="normal", assignee_ids=[str(reviewer)] if reviewer else None,
                        labels=["healthcare-practice-management", "document-filing", "review"],
                    )
                if reviewer:
                    api.notify.send(title=res["label"] + " filed for " + label, body=body[:500], user_ids=[str(reviewer)])
                filed += 1
                done_ids.append(att_key)
            else:
                # Not certain: ask a person which patient (or whether to file at all).
                cand_lines = [patient_name(c) + " - DOB " + str(c.get("date_of_birth") or "not on file") + " - Cliniko ID " + str(c.get("id"))
                              for c in candidates[:5]]
                reason = ("no Cliniko patient matched " + (first + " " + last).strip() if kind in FILEABLE_TYPES and not candidates
                          else "the document has no date of birth to confirm the match" if kind in FILEABLE_TYPES and not dob
                          else str(len(candidates)) + " patients matched" if kind in FILEABLE_TYPES
                          else "the AI couldn't tell what the document is or who it's about")
                suggested = candidates[0] if len(candidates) == 1 else None
                item = api.workq.create(
                    title="File document: " + (name or "attachment") + (" for " + patient_name(suggested) if suggested else ""),
                    scope="org",
                    description=(
                        "**From:** " + sender + "  \n**Subject:** " + subject + "  \n**Attachment:** " + name + "  \n"
                        "**Read as:** " + read_as + "  \n**Why it needs you:** " + reason + "\n\n"
                        + (str(extracted.get("summary") or "") + "\n\n" if extracted.get("summary") else "")
                        + ("**Possible patients:**\n" + "\n".join("- " + x for x in cand_lines) + "\n\n" if cand_lines else "")
                        + "Choose below. To file it on a different patient, enter their Cliniko patient ID (it's in the patient's Cliniko address)."
                    ),
                    priority="normal", assignee_ids=[str(reviewer)] if reviewer else None,
                    labels=["healthcare-practice-management", "document-filing"],
                )
                todo_id = str(item["id"])
                api.workq.attach_form(todo_id=todo_id, form_id=params["filing_form"])
                write_json("PracticeManager/DocumentDrafts/" + todo_id + ".json", {
                    "slug": slug, "message_id": message_id, "attachment_id": str(a.get("id") or ""), "name": name,
                    "sender": sender, "subject": subject, "received": received, "extracted": extracted,
                    "suggested_patient_id": str((suggested or {}).get("id") or ""),
                    "suggested_patient_name": patient_name(suggested) if suggested else "",
                })
                audit(slug, tz, SOURCE, "drafted", {"kind": "email_attachment", "id": message_id},
                      "Asked for a person to confirm the patient for '" + name + "' (" + reason + ")", todo_id)
                queued += 1
                done_ids.append(att_key)
        if retry:
            # Leave this email unfinished so the next run tries it again; attachments already handled on it are
            # recorded per attachment in `done`, so they are not filed twice.
            stopped_at = received
            break
        done_ids.append(message_id)

    state["done"] = done_ids[-1000:]
    resume_from = stopped_at or last_seen
    if resume_from:
        # Step back a second so a message sharing the boundary timestamp isn't skipped; `done` stops repeats.
        resume = datetime.datetime.fromisoformat(resume_from.replace("Z", "+00:00")) - datetime.timedelta(seconds=1)
        state["scan_after"] = utc_iso(resume)
    write_json(state_path, state)

outcome = "filed " + str(filed) + ", sent " + str(queued) + " to WorkQ, skipped " + str(skipped) + " non-clinical"
detail = ("problems: " + " | ".join(problems)) if problems else "no problems"
